def match(orders):
    import heapq

    # Each order in book: (priority_key, arrival_time, order_id, qty, is_active)
    buy_book = []   # max heap: (-price, arrival_time, id, qty)
    sell_book = []  # min heap: (price, arrival_time, id, qty)

    trades = []
    order_status = {}  # id -> {'qty': remaining_qty, 'active': bool}
    arrival_counter = 0

    for order in orders:
        arrival_counter += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_status:
                order_status[order_id]['active'] = False

        elif order[0] == 'market':
            order_id = order[1]
            side = order[2]
            qty = order[3]

            if side == 'buy':
                # Match against sell book
                while qty > 0 and sell_book:
                    while sell_book and not order_status.get(sell_book[0][2], {}).get('active', False):
                        heapq.heappop(sell_book)

                    if not sell_book:
                        break

                    price, arrival, sell_id, _ = sell_book[0]
                    sell_qty = order_status[sell_id]['qty']

                    trade_qty = min(qty, sell_qty)
                    trades.append([order_id, sell_id, price, trade_qty])

                    qty -= trade_qty
                    order_status[sell_id]['qty'] -= trade_qty

                    if order_status[sell_id]['qty'] == 0:
                        heapq.heappop(sell_book)
            else:
                # Match against buy book
                while qty > 0 and buy_book:
                    while buy_book and not order_status.get(buy_book[0][2], {}).get('active', False):
                        heapq.heappop(buy_book)

                    if not buy_book:
                        break

                    neg_price, arrival, buy_id, _ = buy_book[0]
                    price = -neg_price
                    buy_qty = order_status[buy_id]['qty']

                    trade_qty = min(qty, buy_qty)
                    trades.append([buy_id, order_id, price, trade_qty])

                    qty -= trade_qty
                    order_status[buy_id]['qty'] -= trade_qty

                    if order_status[buy_id]['qty'] == 0:
                        heapq.heappop(buy_book)

        elif order[0] in ['limit', 'ioc']:
            order_id = order[1]
            side = order[2]
            price = order[3]
            qty = order[4]
            is_ioc = order[0] == 'ioc'

            order_status[order_id] = {'qty': qty, 'active': True}

            if side == 'buy':
                # Match against sell book
                while qty > 0 and sell_book:
                    while sell_book and not order_status.get(sell_book[0][2], {}).get('active', False):
                        heapq.heappop(sell_book)

                    if not sell_book:
                        break

                    sell_price, arrival, sell_id, _ = sell_book[0]

                    if sell_price > price:
                        break

                    sell_qty = order_status[sell_id]['qty']
                    trade_qty = min(qty, sell_qty)
                    trades.append([order_id, sell_id, sell_price, trade_qty])

                    qty -= trade_qty
                    order_status[sell_id]['qty'] -= trade_qty
                    order_status[order_id]['qty'] -= trade_qty

                    if order_status[sell_id]['qty'] == 0:
                        heapq.heappop(sell_book)

                # Add to book if limit and has remaining qty
                if qty > 0 and not is_ioc:
                    order_status[order_id]['qty'] = qty
                    heapq.heappush(buy_book, (-price, arrival_counter, order_id, qty))
                else:
                    if is_ioc or qty == 0:
                        order_status[order_id]['active'] = False
            else:
                # Match against buy book
                while qty > 0 and buy_book:
                    while buy_book and not order_status.get(buy_book[0][2], {}).get('active', False):
                        heapq.heappop(buy_book)

                    if not buy_book:
                        break

                    neg_buy_price, arrival, buy_id, _ = buy_book[0]
                    buy_price = -neg_buy_price

                    if buy_price < price:
                        break

                    buy_qty = order_status[buy_id]['qty']
                    trade_qty = min(qty, buy_qty)
                    trades.append([buy_id, order_id, buy_price, trade_qty])

                    qty -= trade_qty
                    order_status[buy_id]['qty'] -= trade_qty
                    order_status[order_id]['qty'] -= trade_qty

                    if order_status[buy_id]['qty'] == 0:
                        heapq.heappop(buy_book)

                # Add to book if limit and has remaining qty
                if qty > 0 and not is_ioc:
                    order_status[order_id]['qty'] = qty
                    heapq.heappush(sell_book, (price, arrival_counter, order_id, qty))
                else:
                    if is_ioc or qty == 0:
                        order_status[order_id]['active'] = False

    return trades

